mapper.select:
SELECT a.audit_id, a.admin_user_id, u.email AS admin_email, a.action, a.target_type, a.target_id, a.before, a.after, a.created_at FROM tb_admin_audit_log a LEFT JOIN tb_user u ON u.user_id = a.admin_user_id
a.target_type = #{targetType}
ORDER BY a.created_at DESC, a.audit_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT e.auth_event_id AS id, e.type, e.session_id, e.client, e.ip, e.user_agent, e.created_at
  FROM tb_auth_event e
 WHERE e.user_id = #{userId}
 ORDER BY e.created_at DESC, e.auth_event_id DESC
 LIMIT #{limit}
